import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        // best: rightmost position of the smallest character in the suffix; left: the earliest
        // position with a smaller character after it, right: that character's rightmost position.
        int best = n - 1, left = -1, right = -1;
        for (int i = n - 2; i >= 0; i--) {
            if (s.charAt(i) > s.charAt(best)) {
                left = i;
                right = best;
            } else if (s.charAt(i) < s.charAt(best)) {
                best = i;
            }
        }
        if (left < 0) {
            System.out.println(s);
            return;
        }
        System.out.println(s.substring(0, left) + s.charAt(right) + s.substring(left, right) + s.substring(right + 1));
    }
}

package main

import (
	"io"
	"os"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	n := len(s)
	// best: rightmost position of the smallest character in the suffix; left: the earliest
	// position with a smaller character after it, right: that character's rightmost position.
	best, left, right := n-1, -1, -1
	for i := n - 2; i >= 0; i-- {
		if s[i] > s[best] {
			left, right = i, best
		} else if s[i] < s[best] {
			best = i
		}
	}
	out := make([]byte, 0, n+1)
	if left < 0 {
		out = append(out, s...)
	} else {
		out = append(out, s[:left]...)
		out = append(out, s[right])
		out = append(out, s[left:right]...)
		out = append(out, s[right+1:]...)
	}
	os.Stdout.Write(append(out, '\n'))
}
